package com.fireplatform.configuration;

import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import static org.assertj.core.api.Assertions.*;

class AlarmChangeReconnectPolicyTest {
    MockEnvironment env(String... pairs){var env=new MockEnvironment();for(int i=0;i<pairs.length;i+=2)env.setProperty("APP_ALARM_CHANGE_RECONNECT_"+pairs[i],pairs[i+1]);return env;}
    @Test void defaultsAreDisabledAndOnlyThreeTechnicalBounds(){var p=new AlarmChangeReconnectPolicy(env());assertThat(p.enabled()).isFalse();assertThat(p.maxRetries()).isEqualTo(3);assertThat(p.delayMs()).isEqualTo(1000);assertThat(p.windowMs()).isEqualTo(60000);}
    @Test void environmentAndAppNamesAreConsumedWithAppPrecedence(){var e=env("ENABLED","true","MAX_RETRIES","7","DELAY_MS","250","WINDOW_MS","3000");var p=new AlarmChangeReconnectPolicy(e);assertThat(p.enabled()).isTrue();assertThat(p.maxRetries()).isEqualTo(7);assertThat(p.delayMs()).isEqualTo(250);assertThat(p.windowMs()).isEqualTo(3000);e.setProperty("app.alarm-change-reconnect-enabled","false");e.setProperty("app.alarm-change-reconnect-max-retries","2");e.setProperty("app.alarm-change-reconnect-delay-ms","100");e.setProperty("app.alarm-change-reconnect-window-ms","1000");p=new AlarmChangeReconnectPolicy(e);assertThat(p.enabled()).isFalse();assertThat(p.maxRetries()).isEqualTo(2);assertThat(p.delayMs()).isEqualTo(100);assertThat(p.windowMs()).isEqualTo(1000);}
    @Test void inclusiveNumericEndpointsAreAccepted(){var low=new AlarmChangeReconnectPolicy(env("MAX_RETRIES","1","DELAY_MS","100","WINDOW_MS","1000"));assertThat(low.maxRetries()).isEqualTo(1);assertThat(low.delayMs()).isEqualTo(100);assertThat(low.windowMs()).isEqualTo(1000);var high=new AlarmChangeReconnectPolicy(env("MAX_RETRIES","10","DELAY_MS","60000","WINDOW_MS","600000"));assertThat(high.maxRetries()).isEqualTo(10);assertThat(high.delayMs()).isEqualTo(60000);assertThat(high.windowMs()).isEqualTo(600000);}
    @Test void outOfRangeAndMalformedSettingsFailClosed(){for(String[] pair:new String[][]{{"MAX_RETRIES","0"},{"MAX_RETRIES","11"},{"DELAY_MS","99"},{"DELAY_MS","60001"},{"WINDOW_MS","999"},{"WINDOW_MS","600001"},{"MAX_RETRIES","1.5"},{"WINDOW_MS","not-number"},{"ENABLED","not-boolean"}})assertThatThrownBy(()->new AlarmChangeReconnectPolicy(env(pair))).isInstanceOf(RuntimeException.class);}
    @Test void windowMustStrictlyExceedDelayEvenForAnExplicitDisabledConfiguration(){for(String window:new String[]{"1000","1500"})assertThatThrownBy(()->new AlarmChangeReconnectPolicy(env("DELAY_MS","1500","WINDOW_MS",window))).isInstanceOf(IllegalStateException.class);assertThat(new AlarmChangeReconnectPolicy(env("DELAY_MS","1500","WINDOW_MS","1501")).windowMs()).isEqualTo(1501);}
    @Test void newDefaultsDoNotNarrowValidB2ConnectOrSilenceConfiguration(){var e=env();e.setProperty("app.alarm-change-ws-connect-timeout-ms","60000");e.setProperty("app.alarm-change-ws-silence-timeout-ms","180000");assertThat(new AlarmChangeChannelPolicy(e).connectTimeoutMs()).isEqualTo(60000);assertThat(new AlarmChangeReconnectPolicy(e).enabled()).isFalse();e.setProperty("APP_ALARM_CHANGE_RECONNECT_ENABLED","true");assertThat(new AlarmChangeReconnectPolicy(e).windowMs()).isEqualTo(60000);}
}
